import random
import struct
import itertools

# Generator for arbitrary bytes targeting libqrencode-style fuzzers.
# Focus: produce valid, interesting byte buffers that exercise QR encoding paths:
# - Numeric-only, Alphanumeric, 8-bit binary (including NULs), Kanji-like Shift-JIS pairs
# - Mixes of segments, varying lengths, repeated patterns, ECI-like markers embedded
# - Sizes appropriate for normal and Micro QR, structured append, and append/check
# Output limited to <= 4096 bytes.

ALNUM_CHARS = b"0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ $%*+-./:"
NUMERIC_CHARS = b"0123456789"

# Some Shift-JIS Kanji ranges commonly used in QR Kanji mode (JIS X 0208) when mapped to Shift_JIS):
# We'll craft plausible double-bytes in primary ranges avoid invalid lead/trail combos.
# Ranges below are heuristics to create many valid-ish SJIS double-byte pairs.
SJIS_LEADS = list(range(0x81, 0x9F + 1)) + list(range(0xE0, 0xEF + 1))
SJIS_TRAILS = list(range(0x40, 0x7E + 1)) + list(range(0x80, 0xFC + 1))

# Common prefixes and payloads to exercise ECI/GS1-like content in 8-bit data encode APIs.
COMMON_PREFIXES = [
    b"HELLO WORLD",
    b"HTTP://EXAMPLE.COM/TEST?A=1&B=2",
    b"WIFI:S:MyNet;T:WPA;P:pass1234;;",
    b"MATMSG:TO:foo@example.com;SUB:Hello;BODY:Test;;",
    b"SMSTO:+1234567890:Meet at 5?",
    b"MAILTO:dev@example.com",
    b"BEGIN:VCARD\nVERSION:3.0\nN:Doe;John;;;\nTEL:+123456\nEND:VCARD\n",
]

BINARY_PATTERNS = [
    b"\x00" * 32,                 # many NULs
    bytes(range(256)),             # 0..255
    bytes(reversed(range(256))),   # 255..0
    b"\xFF\x00" * 64,            # alternating
    b"\xAA\x55" * 64,            # pattern
]

# Some sizes tuned for QR and Micro QR capacities with L/M/Q/H EC levels.
# We'll cap size selection elsewhere; here we provide baseline target sizes.
INTERESTING_SIZES = [0, 1, 2, 3, 7, 14, 17, 25, 31, 33, 64, 70, 80, 100, 127, 160, 200, 255, 300, 351, 400, 512, 700, 800, 1024]

MAX_OUT = 4096


def _rand_numeric(rng: random.Random, n: int) -> bytes:
    return bytes(rng.choice(NUMERIC_CHARS) for _ in range(n))


def _rand_alnum(rng: random.Random, n: int) -> bytes:
    return bytes(rng.choice(ALNUM_CHARS) for _ in range(n))


def _rand_sjis_kanji(rng: random.Random, n_kanji: int) -> bytes:
    out = bytearray()
    for _ in range(n_kanji):
        lead = rng.choice(SJIS_LEADS)
        trail = rng.choice(SJIS_TRAILS)
        out.append(lead)
        out.append(trail)
    return bytes(out)


def _rand_binary(rng: random.Random, n: int) -> bytes:
    return rng.randbytes(n)


def _mix_segments(rng: random.Random, segments: list[bytes]) -> bytes:
    rng.shuffle(segments)
    return b"".join(segments)


def _with_length_prefix(rng: random.Random, data: bytes) -> bytes:
    # Some consumers use an external size, but adding an internal length prefix can
    # exercise code paths that read sub-buffers.
    # We randomly choose 8/16/32-bit length fields in little/big endian.
    choice = rng.randrange(6)
    if choice == 0:
        return struct.pack("<B", len(data) & 0xFF) + data
    if choice == 1:
        return struct.pack(">B", len(data) & 0xFF) + data
    if choice == 2:
        return struct.pack("<H", len(data) & 0xFFFF) + data
    if choice == 3:
        return struct.pack(">H", len(data) & 0xFFFF) + data
    if choice == 4:
        return struct.pack("<I", len(data) & 0xFFFFFFFF) + data
    return struct.pack(">I", len(data) & 0xFFFFFFFF) + data


def _maybe_insert_nuls(rng: random.Random, data: bytes) -> bytes:
    # Insert NULs at random positions to ensure QRcode_encodeData paths handle embedded zeros.
    if not data:
        return data
    pieces = []
    idx = 0
    while idx < len(data):
        step = rng.randint(1, max(1, len(data)//8))
        pieces.append(data[idx:idx+step])
        if rng.random() < 0.3:
            pieces.append(b"\x00" * rng.randint(1, 3))
        idx += step
    return b"".join(pieces)


def _structured_like_chunks(rng: random.Random) -> bytes:
    # Create content that could be split into multiple symbols: repeated headers and payloads.
    chunks = []
    parts = rng.randint(2, 6)
    base = rng.choice(COMMON_PREFIXES)
    for i in range(parts):
        hdr = f"PART:{i+1}/{parts};".encode()
        pay_len = rng.randint(10, 80)
        payload = _rand_alnum(rng, pay_len)
        chunks.append(hdr + base[: rng.randint(0, len(base))] + b";DATA=" + payload)
    return b"|".join(chunks)


def _eci_like_header(rng: random.Random) -> bytes:
    # Create a synthetic ECI-like header followed by UTF-8 text; though QRcode_encodeData
    # treats everything as 8-bit, embedding this may hit library branches around ECI handling
    # in other stubs.
    ecinum = rng.randrange(0, 999999)
    return f"ECI:{ecinum};".encode()


def _cap(b: bytes) -> bytes:
    return b[:MAX_OUT]


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Strategy selection: pick a template to generate content.
    strat = rng.randrange(10)

    if strat == 0:
        # Pure numeric (QR_MODE_NUM valid input)
        n = rng.choice([0, 1, 3, 7, 10, 20, 40, 64, 127, 255, 512, 800, 1024])
        data = _rand_numeric(rng, n)
        return _cap(data)

    if strat == 1:
        # Pure alphanumeric (QR_MODE_AN valid input)
        n = rng.choice([1, 2, 5, 11, 25, 47, 70, 100, 160, 255, 400, 700, 1024])
        data = _rand_alnum(rng, n)
        return _cap(data)

    if strat == 2:
        # Kanji-like Shift-JIS pairs (QR_MODE_KANJI)
        k = rng.choice([1, 2, 4, 8, 16, 32, 64, 100, 128, 200])
        data = _rand_sjis_kanji(rng, k)
        return _cap(data)

    if strat == 3:
        # Pure binary 8-bit including NULs
        n = rng.choice([0, 1, 4, 8, 16, 32, 64, 128, 256, 400, 700, 1024])
        base = _rand_binary(rng, n)
        # Blend with a known binary pattern to increase structure
        if rng.random() < 0.6:
            pat = rng.choice(BINARY_PATTERNS)
            data = (base + pat)[: max(n, len(pat))]
        else:
            data = base
        data = _maybe_insert_nuls(rng, data)
        return _cap(data)

    if strat == 4:
        # Mixed segments: numeric + alnum + binary
        segs = []
        segs.append(_rand_numeric(rng, rng.randint(5, 40)))
        segs.append(_rand_alnum(rng, rng.randint(10, 60)))
        segs.append(_maybe_insert_nuls(rng, _rand_binary(rng, rng.randint(5, 40))))
        if rng.random() < 0.5:
            segs.append(_rand_sjis_kanji(rng, rng.randint(1, 8)))
        data = _mix_segments(rng, segs)
        return _cap(data)

    if strat == 5:
        # Common prefixes + payload, good for encodeData and structured
        prefix = rng.choice(COMMON_PREFIXES)
        payload_len = rng.choice([13, 31, 57, 89, 128, 223, 351, 521])
        payload = _rand_alnum(rng, payload_len)
        if rng.random() < 0.5:
            payload = _maybe_insert_nuls(rng, payload)
        data = prefix + b"|" + payload
        return _cap(data)

    if strat == 6:
        # Structured-like multi-part content
        data = _structured_like_chunks(rng)
        if rng.random() < 0.4:
            data = _with_length_prefix(rng, data)
        return _cap(data)

    if strat == 7:
        # ECI-like header + UTF-8/ASCII content + some binary tail
        head = _eci_like_header(rng)
        text = rng.choice(COMMON_PREFIXES)
        tail = _rand_binary(rng, rng.randint(0, 64))
        data = head + text + b";BIN=" + _maybe_insert_nuls(rng, tail)
        return _cap(data)

    if strat == 8:
        # Size-targeted payload: choose an interesting length and fill with safe 8-bit bytes
        target = rng.choice(INTERESTING_SIZES)
        # Compose from chunks to reach near target length
        chunks = []
        remaining = target
        while remaining > 0:
            choice = rng.randrange(4)
            if choice == 0:
                c = _rand_alnum(rng, min(remaining, rng.randint(5, 40)))
            elif choice == 1:
                c = _rand_numeric(rng, min(remaining, rng.randint(3, 20)))
            elif choice == 2:
                kbytes = min(remaining // 2, rng.randint(1, 8)) * 2
                c = _rand_sjis_kanji(rng, kbytes // 2) if kbytes > 0 else b""
            else:
                c = _rand_binary(rng, min(remaining, rng.randint(4, 32)))
            chunks.append(c)
            remaining -= len(c)
            if remaining <= 0:
                break
        data = b"".join(chunks)
        if rng.random() < 0.3:
            data = _maybe_insert_nuls(rng, data)
        return _cap(data)

    # strat == 9: Prefix with internal length then mixed content
    base = _mix_segments(
        rng,
        [
            _rand_alnum(rng, rng.randint(10, 50)),
            _rand_numeric(rng, rng.randint(5, 30)),
            _rand_binary(rng, rng.randint(5, 25)),
        ],
    )
    if rng.random() < 0.5:
        base += _rand_sjis_kanji(rng, rng.randint(1, 6))
    data = _with_length_prefix(rng, base)
    return _cap(data)
